import{_ as a,o,c,a2 as d}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"网易云合伙人-自动任务","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/features/netease-partner.md","filePath":"projects/lotus-plugin/docs/features/netease-partner.md"}'),s={name:"projects/lotus-plugin/docs/features/netease-partner.md"};function n(t,e,r,p,i,l){return o(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="网易云合伙人-自动任务" tabindex="-1">网易云合伙人-自动任务 <a class="header-anchor" href="#网易云合伙人-自动任务" aria-label="Permalink to &quot;网易云合伙人-自动任务&quot;">​</a></h1><p>返回：<a href="./../README.html">文档目录</a> / <a href="./README.html">小功能索引</a></p><h2 id="初始化与登录" tabindex="-1">初始化与登录 <a class="header-anchor" href="#初始化与登录" aria-label="Permalink to &quot;初始化与登录&quot;">​</a></h2><p>仅机器人主人可操作，按顺序发送：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#初始化环境</span></span>
<span class="line"><span>#TuneWeave状态</span></span>
<span class="line"><span>#合伙人登录</span></span>
<span class="line"><span>#合伙人测试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>#合伙人测试</code> 会实际提交评分和配置的乐评，也接受 <code>#合伙人测试（执行）</code>。<code>#合伙人日志</code> 以合并转发查看当天日志中的歌曲、主分、各子项分数、对应乐评及每轮结果。</p><p>统一 <code>#初始化环境</code> 会准备适合当前系统的 TuneWeave 官方预编译文件，校验 SHA-256 后启动本机服务；已有可用实例直接复用。音乐、视频和合伙人共用同一服务，不再要求为合伙人单独下载。旧 <code>#初始化TuneWeave</code> 保留为只准备该服务的入口。初始化完成后，Yunzai 重启会恢复本机服务；默认三分钟后检查最新官方清单与程序完整性，必要时校验更新、重启服务并通知主人，详见 <a href="./../initialization.html#tuneweave-开机更新">开机更新</a>。默认地址为 <code>http://127.0.0.1:7832</code>，可通过 <code>tuneweave.api_url</code> 指向其他自托管实例；远程实例须自行部署。缺少所需登录或扩展 API 能力时会明确报错。当前发布物支持 Linux x64、Windows x64/arm64、macOS x64/arm64，其他平台需自行部署。</p><p>网易云点歌与合伙人共用扫码登录；也可发送 <code>#音乐登录</code> 选择网易云。使用网易云音乐 App 扫码，账号凭据由 TuneWeave 服务端托管；Lotus 的 <code>data/netease/accounts.yaml</code> 仅保存账户别名、UID 和任务偏好。首次初始化本机服务时，使用 TuneWeave 官方启动 Cookie 配置承接第一个旧账号；该启动凭据只保存在私有 <code>data/tuneweave/bootstrap.json</code> 中。首次任务核验默认账号 UID 后，Lotus 账号文件移除旧 Cookie。多个旧账号中的其余账号、外部实例或身份不一致的账号须重新扫码，旧记录会保留。</p><h2 id="评分与汇报" tabindex="-1">评分与汇报 <a class="header-anchor" href="#评分与汇报" aria-label="Permalink to &quot;评分与汇报&quot;">​</a></h2><p>任务读取、额外任务读取和评分提交全部通过 TuneWeave 的网易云扩展 API。每首作品读取自己的 <code>supportExtraEvaTypes</code>（旧数据兼容 <code>dimensions</code>），每个子项独立打分；<code>extraScore</code> 会完整提交，不能仅发评论与主分。作品没有提供子项时，报告明确标注，不补造评分维度。</p><p>每个账号每日目标 20 首，完成数不足 20 时再重试一轮；两轮按作品 ID 合并，已完成作品不重复提交，最终只汇报一次。图片仅显示成功、失败数量；日志记录歌曲、主分、全部子项分数、对应乐评和每轮结果。已完成作品计入成功数。登录成功后启用自动任务，仍按 <code>netease_partner.schedule</code> 每日执行；默认每天 00:05，已有自定义 cron 保留。<code>notify_master: true</code> 时，自动任务给主人发送汇报图。启动补跑由 <code>auto_catch_up</code> 控制；手动与定时任务并发时只执行一轮。</p><p>乐评在主人管理面板的“网易云任务”中配置，也可编辑本机 <code>config/global.yaml</code> 的 <code>netease_partner.review</code>。默认 <code>mode: fixed</code>，沿用 <code>netease_partner.comments</code> 中的评论库；每轮优先不重复抽取，用完才循环，更新不会覆盖已有评论库。本机乐评库不纳入源码仓库。</p><p><code>mode: codex</code> 使用机器人运行用户已登录的本机 Codex CLI，无需配置 API 密钥；<code>codex_command</code> 默认 <code>codex</code>，也可填写程序绝对路径。<code>mode: responses</code> 使用 <code>api_url</code> 指定的 Responses 接口及私有 <code>api_key</code>，服务须支持 <code>web_search</code> 工具。两种 AI 模式均结合本次任务拿到的歌曲、作者、风格与歌词等信息联网查证；缺少或无法确认的资料不编造，不冒充已经试听。Codex CLI 的 <code>model</code> 留空沿用本机默认模型；Responses API 必须明确填写 <code>model</code>。</p><p>AI 乐评通常写 40～80 字，用一两句日常表达说明具体看法，不写成鉴赏文章，也不刻意写满上限；配置的上限低于目标长度时，以配置为准。<code>max_chars</code> 默认 140，可设为 20～500 个字符，控制本地提交长度。<code>timeout_ms</code> 默认 180000 毫秒。AI 生成失败、超时或资料不足时，跳过本首评论并记录原因，不回退到无关套话；账号关闭评论时同样明确标注未发布。日志记录每首作品实际提交的乐评。切换到 AI 模式不会删除原有固定评论库。</p><p>自动任务按日去重：当天执行过后，重复 cron 触发不再执行或汇报；失败重试已包含在同一次任务中。手动 <code>#合伙人测试</code> 仍可显式执行。</p><h2 id="数据与配置" tabindex="-1">数据与配置 <a class="header-anchor" href="#数据与配置" aria-label="Permalink to &quot;数据与配置&quot;">​</a></h2><ul><li><code>tuneweave.api_url</code>：自托管服务地址。</li><li><code>tuneweave.request_timeout_ms</code>：请求超时，默认 30000 毫秒。</li><li><code>netease_partner</code>：定时、通知、登录超时、操作间隔与固定评论库。</li><li><code>netease_partner.review</code>：乐评生成方式、字数与超时限制、Codex CLI 程序及 Responses 接口配置；原来用于网易云服务的顶层 <code>netease_partner.api_url</code> 已移除，与这里的 <code>review.api_url</code> 无关。</li><li><code>data/tuneweave/</code>：本机可执行文件、私有账户数据与日志。</li><li><code>data/netease/accounts.yaml</code>：Lotus 账号信息；<code>data/netease/state.yaml</code>：任务状态。</li><li><code>data/logs/nep-latest.json</code>：当天最新的逐作品评分报告，次日执行覆盖；旧的带时间戳合伙人日志会清理，其他功能日志保留。</li></ul><p>账户数据和旧配置备份含有秘密，不应上传。</p>`,18)])])}const _=a(s,[["render",n]]);export{m as __pageData,_ as default};
